mapper.select:
SELECT enabled
FROM iam_resource_operation
WHERE tenant_id = #{tenantId} AND resource_id = #{resourceId}
  AND operation_id = #{operationId}

mapper.update:
UPDATE iam_role_permission
SET status = 'REVOKED', active_slot = NULL, version = version + 1,
    updated_at = #{now}
WHERE tenant_id = #{tenantId} AND role_id = #{roleId}
  AND status = 'ACTIVE' AND active_slot = 1

UPDATE iam_team_role_permission
SET status = 'REVOKED', active_slot = NULL, version = version + 1,
    updated_at = #{now}
WHERE tenant_id = #{tenantId} AND team_role_id = #{teamRoleId}
  AND status = 'ACTIVE' AND active_slot = 1

UPDATE iam_resource_field
SET status = 'DISABLED', version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND resource_id = #{resourceId}
  AND status = 'ACTIVE'
